theorem exists_hyperplane_superset_notMem (hF : M.IsFlat F) {e : α}
    (heE : e ∈ M.E) (heF : e ∉ F) :
    ∃ H : Set α, IsHyperplane M H ∧ F ⊆ H ∧ e ∉ H

theorem natRank_closure_insert {S : Set α} (hS : M.IsFlat S) {e : α}
    (he : e ∈ M.E) (heS : e ∉ S) :
    natRank M (M.closure (insert e S)) = natRank M S + 1

theorem exists_constant_path {F X : Set α} {Γ : Set (Set α)}
    (hX : IsHyperplane M X) (hFX : F ⊆ X) (hXoff : X ∉ Γ) :
    ∃ p : TuttePath M, p.origin = X ∧ p.terminus = X ∧ p.On F ∧ p.Off Γ

theorem exactCut_liftContraction (φ : ModelEmbedding N (M ／ D)) (hD : M.IsFlat D)
    (h0 : N.Flat ∅) {Γ : Set (Set α)} {C : Finset (Finset (Fin n))}
    (h : ExactCut φ (contractionCut M D Γ) C) : ExactCut (φ.liftContraction hD h0) Γ C

theorem BaseElementary.liftContraction {Γ : Set (Set α)} {p : TuttePath (M ／ D)}
    (h : BaseElementary (M ／ D) (contractionCut M D Γ) p) (hD : M.IsFlat D) :
    BaseElementary M Γ (p.liftContraction hD)

theorem Lower.null_of_on {n : ℕ} (h : Lower M Γ n) {p : TuttePath M} {D : Set α}
    (hc : Closed p) (hoff : p.Off Γ) (hon : p.On D)
    (hr : natRank M M.E - natRank M D ≤ n) : NullHomotopic M Γ p

theorem homotopic_of_null_comparison (hΓ : ModularCut M Γ) {p q : TuttePath M}
    (ho : p.origin = q.origin) (ht : p.terminus = q.terminus)
    (h : NullHomotopic M Γ (p.concat q.reverse (by simpa using ht))) : Homotopic M Γ p q

theorem four_cube_triples_parity : ∀ C : Finset (Fin 8), C.card = 4 →
    (∀ i ∈ C, ∀ j ∈ C, i ≠ j → (cubeTriple i ∩ cubeTriple j).card ≤ 1) →
    C = {0,3,5,6} ∨ C = {1,2,4,7}

theorem image_hyperplane (φ : ModelEmbedding N M) {F : Finset (Fin n)}
    (hF : N.Flat F) (hrF : N.rank F + 1 = N.rank Finset.univ) :
    IsHyperplane M (φ.image F)

theorem contracted_representatives_injective {ι : Type*} {D : Set α}
    (P : ι → Set α) (hDP : ∀ i, D ⊆ P i) (hinj : Function.Injective P)
    (e : ι → α) (he : ∀ i, (M ／ D).closure {e i} = P i \ D) : Function.Injective e

theorem adjacent_union_contract (hD : M.IsFlat D) {H K : Set α}
    (hH : (M ／ D).IsFlat H) (hK : (M ／ D).IsFlat K)
    (he : TutteAdjacent (M ／ D) H K) : TutteAdjacent M (H ∪ D) (K ∪ D)

theorem noncover_of_same_trace {E W I X Z : Set α}
    (hX : X ⊆ E) (hW : W ⊆ E) (hWI : W ∪ I = E)
    (htrace : I ∩ X = I ∩ Z) (hn : X ∪ W ≠ E) : Z ∪ W ≠ E

theorem homotopic_right_division (hΓ : ModularCut M Γ) {a b c : TuttePath M}
    (hab : a.terminus = b.origin) (h : Homotopic M Γ (a.concat b hab) c) :
    Homotopic M Γ a (c.concat b.reverse (by simpa using h.endpoints.2.symm))

theorem mem_cutPlus_contractionCut_iff (hD : M.IsFlat D) {Γ : Set (Set α)}
    (hF : (M ／ D).IsFlat F) :
    F ∈ cutPlus (M ／ D) (contractionCut M D Γ) ↔ F ∪ D ∈ cutPlus M Γ

theorem Elementary.liftContraction {Γ} {p : TuttePath (M ／ D)}
    (h : Elementary (M ／ D) (contractionCut M D Γ) p) (hD : M.IsFlat D) :
    Elementary M Γ (p.liftContraction hD)

theorem ElementaryStep.liftContraction {Γ} {p q : TuttePath (M ／ D)}
    (h : ElementaryStep (M ／ D) (contractionCut M D Γ) p q) (hD : M.IsFlat D) :
    ElementaryStep M Γ (p.liftContraction hD) (q.liftContraction hD)

theorem Homotopic.liftContraction {Γ} {p q : TuttePath (M ／ D)}
    (h : Homotopic (M ／ D) (contractionCut M D Γ) p q) (hD : M.IsFlat D) :
    Homotopic M Γ (p.liftContraction hD) (q.liftContraction hD)

theorem NullHomotopic.liftContraction {Γ} {p : TuttePath (M ／ D)}
    (h : NullHomotopic (M ／ D) (contractionCut M D Γ) p) (hD : M.IsFlat D) :
    NullHomotopic M Γ (p.liftContraction hD)

theorem contracted_points_complete {P : Set α} (hP : Indecomposable (M ／ s.D) P)
    (hrP : natRank (M ／ s.D) P = 1) :
    ∃ i, P = (M ／ s.D).closure {d.representative i}
